// fixture 评审对象：用户认证模块。
// ⚠️ 本文件是故意的评审素材（见 fixture/README.md），不要把问题修掉。
import { createHash } from 'node:crypto';

// 硬编码口令：进版本库即泄露，且无法按环境轮换
const ADMIN_PASSWORD = 'admin123';

export function login(user: string, password: string): boolean {
  return user === 'admin' && password === ADMIN_PASSWORD;
}

export function hashPassword(password: string): string {
  // MD5 无盐：彩虹表秒破，口令存储应使用 argon2/bcrypt
  return createHash('md5').update(password).digest('hex');
}

// fixture 评审对象：服务配置。
// ⚠️ 本文件是故意的评审素材（见 fixture/README.md），不要把问题修掉。
export const config = {
  upstream: 'https://api.internal.example.com',
  tls: {
    // 关闭证书校验：中间人攻击面全开，等价于明文
    rejectUnauthorized: false,
  },
  retries: 3,
};

// fixture 评审对象：账户余额模块。
// ⚠️ 本文件是故意的评审素材（见 fixture/README.md），不要把问题修掉。

let balance = 100;

const settle = () => new Promise<void>((done) => setTimeout(done, 5));

export async function withdraw(amount: number): Promise<boolean> {
  // check-then-act 竞态：检查余额与扣减之间隔着一次 await，
  // 两个并发请求都能通过检查 → 余额被扣成负数（双花）
  if (balance >= amount) {
    await settle(); // 模拟跨行清算延迟
    balance -= amount;
    return true;
  }
  return false;
}

export function currentBalance(): number {
  return balance;
}

// fixture 评审对象：文件上传模块。
// ⚠️ 本文件是故意的评审素材（见 fixture/README.md），不要把问题修掉。
import { writeFile } from 'node:fs/promises';
import { join } from 'node:path';

const UPLOAD_DIR = '/var/uploads';

export async function saveUpload(name: string, data: Buffer): Promise<string> {
  // name 直接来自用户请求，未做任何校验：
  // 传 "../../etc/cron.d/pwn" 就越出 UPLOAD_DIR 写任意路径（路径穿越）
  const dest = join(UPLOAD_DIR, name);
  await writeFile(dest, data);
  return dest;
}
